package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet: everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms (in days) a sheet starts with. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's "today": every date decision and default date on the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last number given to a claim opened on the sheet; 0 before the first. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** A clerk settles a claim only when its due is at or below this; null when there is no limit. */
    @Column(name = "clerk_limit", precision = 15, scale = 2)
    private BigDecimal clerkLimit;

    /** A claim's live due is at least this. */
    @Column(name = "due_floor", nullable = false, precision = 15, scale = 2)
    private BigDecimal floor = DEFAULT_FLOOR;

    /** A claim is due by its date plus this many days. */
    @Column(name = "terms", nullable = false)
    private int terms = DEFAULT_TERMS;

    /** An overdue claim's due gains this percent of its figure for every full 30 days it is overdue. */
    @Column(name = "late_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal latePct = DEFAULT_LATE_PCT;

    /** A claim dated before this rounds half up, one on or after it half to even; null when blank,
     *  when the sheet's today is the policy date. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** While set and the sheet's today is on or after it, a claim opened is numbered within its
     *  period; null when blank (off), when claims take the sheet-wide numbers. */
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** A person on a sheet, with a name and a dated grade (A, B or C). */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The first grade the person was given: in force from the beginning of time until a later one. */
    @Column(name = "grade", nullable = false)
    private String grade;

    /** The grades recorded since, by the date each is in force from. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    @MapKeyColumn(name = "from_date")
    @Column(name = "grade", nullable = false)
    private Map<LocalDate, String> datedGrades = new HashMap<>();

    /** The date the person is retired from; null while not retired. Set, they count as retired
     *  at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Whether the person is on hold: their OPEN claims then count in no live total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** Raised on every save, so an edit of a version someone else has since saved is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;
-- A person's grade is dated: person.grade is the first grade they were given, applying from the
-- beginning of time, and each later grade is kept here from its from-date (one per from-date). A
-- claim uses the grade in force on its date: the one with the latest from-date on or before it.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE       NOT NULL,
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    PRIMARY KEY (person_id, from_date)
);
-- Where a claim is listed among its person's claims, newest first: the highest on the sheet when it
-- is added, and again when it is reassigned to another person, so a moved claim is listed as its
-- new person's newest whatever its date.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Optional;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;

    public SheetService(SheetRepository sheets, RollupService rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    /** Load a sheet by id; an id never used before starts an empty sheet, its today the real date. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
            } catch (DataIntegrityViolationException e) {
                // another user created it at the same moment
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /** The sheet, if it was ever loaded. */
    @Transactional(readOnly = true)
    public Optional<Sheet> find(String id) {
        return sheets.findById(id);
    }

    /** Write the changes made to a loaded sheet. */
    @Transactional
    public void flush() {
        sheets.flush();
    }

    /** The sheet's today: the date every date decision and default date on the sheet uses. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /** The sheet's floor: a claim's live due is at least it. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String id) {
        return sheets.findById(id).map(Sheet::getFloor).orElse(Sheet.DEFAULT_FLOOR);
    }

    /** The sheet's terms: a claim is due by its date plus this many days. */
    @Transactional(readOnly = true)
    public int terms(String id) {
        return sheets.findById(id).map(Sheet::getTerms).orElse(Sheet.DEFAULT_TERMS);
    }

    /** The sheet's late percent: an overdue claim's due gains it for every full 30 days overdue. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String id) {
        return sheets.findById(id).map(Sheet::getLatePct).orElse(Sheet.DEFAULT_LATE_PCT);
    }

    /** Whether a claim opened now is numbered within its period. */
    @Transactional(readOnly = true)
    public boolean periodNumberingOn(String id) {
        return sheets.findById(id).map(Sheet::isPeriodNumberingOn).orElse(false);
    }

    /** Take the sheet's next claim number (1 for the first), holding the sheet locked until the
     *  transaction ends so numbers are never shared and, if it rolls back, never skipped. */
    @Transactional
    public int nextClaimNumber(String id) {
        Sheet sheet = sheets.findForUpdate(id).orElseThrow();
        int number = sheet.nextClaimNumber();
        sheets.flush();
        return number;
    }

    /** Hold the sheet locked until the transaction ends, so changes checked against the rest of
     *  the sheet (such as a period that must not overlap another) are made one at a time. */
    @Transactional
    public void lock(String id) {
        sheets.findForUpdate(id).orElseThrow();
    }

    /** Change the sheet's today (the sheet is created first if it was never loaded); it has no
     *  audit line of its own, only the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        RollupService.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        rollup.recordChanges(id, user, before);
        return sheet;
    }
}

